Lemma ibc_from_350 : forall (h pos cd prev : Z) (ns : NS) (ll : bool) (nd : Z) (lo hi : Z) (X : list Z)
    (b0 : byte) (j7 : list byte) (w0 : word)
    (ra sp : word) gp tp (x1 t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m m1 : mem) (j8 : list byte),
  NSR m1 ns lo hi X -> nodes_al X -> NSR m ns lo hi X ->
  (get_parent ns h ≫= (λ hp, if hp =? 0 then Some (true, pos)
                            else get_left ns pos ≫= (λ pl, Some (if pl =? 0 then (true, pos) else (false, prev))))) = Some (ll, nd) ->
  rw_cells usegs m1 cd [C1 b0; CB 7 j7; C8 w0] ->
  rw_cells usegs m1 (bv_unsigned sp + -48) [CB 8 j8; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 ra] ->
  stk usegs m1 lo (bv_unsigned sp + -48) -> lo + 64 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= cd -> cd + 16 <= hi ->
  munch [(lo, bv_unsigned sp); (cd, cd + 16)]%Z m m1 -> wmono usegs m m1 -> mem_inv usegs m1 ->
  0 <= h < 2^64 -> 0 <= pos < 2^64 ->
  evt usegs (ibc_post ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc ns cd ll nd j7 lo m)
    (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 pos) (Z_to_bv 64 prev) a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 h) (Z_to_bv 64 cd) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x361b8) fc None m1 (seg_rom usegs)).
