Lemma FieldsC_NSR_new : forall m Fa S L ns ls em e junk lo (sp : word),
  FieldsC m Fa S L ns ls em ->
  rw_cells usegs m (e + 16) [CB 32 junk] ->
  0 < e -> e + 48 <= hceil ->
  (forall e' d', em !! e' = Some d' -> e + 48 <= e' + 16 \/ e' + 48 <= e + 16) ->
  hceil <= lo -> bv_unsigned sp <= Fa ->
  exists ndn pad,
    node_wf ndn /\ rw_cells usegs m (e + 16) (NodeCells ndn pad)
