(* [comment removed for export] *)
Lemma FieldsC_nodes_al : forall m Fa S L ns ls em e,
  FieldsC m Fa S L ns ls em -> 0 < e -> e mod 8 = 0 -> nodes_al (Fa :: (e + 16) :: S).
Proof.
  intros m Fa S L ns ls em e FC EP EAL x IN. pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & HHF & HB & AL). hcb.
  rewrite !elem_of_cons in IN. destruct IN as [->|[->|IN]].
  - split; [lia| exact AL].
  - split; [lia|]. replace (e + 16) with (e + 2 * 8) by lia. rewrite Z_mod_plus_full. exact EAL.
  - exact (TreeR_node_al _ _ _ _ _ _ (FieldsC_TreeR _ _ _ _ _ _ _ FC) IN) ||
    (pose proof (TreeR_node_al _ _ _ _ _ _ (FieldsC_TreeR _ _ _ _ _ _ _ FC) IN) as [P Q]; split; [lia| exact Q]).
Qed.

Lemma FieldsC_cols_new : forall m Fa S L ns ls em n ndn,
  FieldsC m Fa S L ns ls em -> cols_ok [n] (<[ n := ndn ]> ns).
Proof.
  intros m Fa S L ns ls em n ndn FC a nd La NI. pose proof FC as (NC & LC & EC & (T & HS & HR & HD & HCO) & _).
  destruct (Z.eq_dec a n) as [->|NE].
  - exfalso. apply NI. rewrite elem_of_cons. left; reflexivity.
  - rewrite lookup_insert_ne in La by (intros E; apply NE; symmetry; exact E).
    apply (HCO a nd La). rewrite elem_of_nil. intros F; exact F.
Qed.
End HCW3.
